const INSTRUMENTAL_BGM_GENRE_IDS = new Set([
  'instrumental_bgm',
  'lofi_study',
  'cafe_bgm',
  'nature_ambience',
  'healing_piano',
  'ambient',
  'minimalism',
  'piano_solo',
  'string_ensemble',
]);

const isInstrumentalBgmId = (value?: string | null) => Boolean(value && INSTRUMENTAL_BGM_GENRE_IDS.has(String(value)));

type BgmBpmRange = { min: number; max: number };

const INSTRUMENTAL_BGM_DEFAULT_BPM: Record<string, BgmBpmRange> = {
  lofi_study: { min: 66, max: 88 },
  cafe_bgm: { min: 74, max: 98 },
  nature_ambience: { min: 38, max: 62 },
  healing_piano: { min: 46, max: 74 },
  ambient: { min: 42, max: 70 },
  minimalism: { min: 60, max: 104 },
  piano_solo: { min: 44, max: 78 },
  string_ensemble: { min: 50, max: 84 },
};

const INSTRUMENTAL_BGM_SLOW_MOODS = new Set([
  'calm', 'relaxing', 'zen', 'healing', 'peaceful', 'restrained',
  'sad', 'sorrowful', 'melancholic', 'lonely', 'wistful', 'hollow',
  'dark', 'moody', 'chilly', 'fragile_edge', 'soft_tender', 'tender',
]);

const INSTRUMENTAL_BGM_FAST_MOODS = new Set([
  'bright', 'hopeful', 'cheerful', 'playful_mischief', 'cheeky_deadpan',
  'comedic', 'quirky', 'cute_mood', 'upbeat', 'swelling', 'powerful',
  'infectious', 'tense', 'uneasy', 'groovy',
]);

function getInstrumentalBgmMainId(params: Pick<GenerateSongParams, 'genre' | 'subGenre'>): string | null {
  const ids = [...(params.subGenre || []), params.genre || ''].filter(Boolean);
  return ids.find((id) => isInstrumentalBgmId(id)) || null;
}

function getInstrumentalBgmDefaultTempo(params: Pick<GenerateSongParams, 'genre' | 'subGenre' | 'moods'>): string {
  const mainId = getInstrumentalBgmMainId(params);
  if (!mainId) return '';
  const base = INSTRUMENTAL_BGM_DEFAULT_BPM[mainId] || { min: 54, max: 88 };
  const moods = params.moods || [];
  const slowHits = moods.filter((id) => INSTRUMENTAL_BGM_SLOW_MOODS.has(id)).length;
  const fastHits = moods.filter((id) => INSTRUMENTAL_BGM_FAST_MOODS.has(id)).length;
  const shift = Math.max(-12, Math.min(12, (fastHits - slowHits) * 4));
  let min = Math.max(20, Math.min(200, Math.round(base.min + shift)));
  let max = Math.max(20, Math.min(200, Math.round(base.max + shift)));
  if (['nature_ambience', 'ambient'].includes(mainId)) max = Math.min(max, 78);
  if (['healing_piano', 'piano_solo', 'string_ensemble'].includes(mainId)) max = Math.min(max, 92);
  return `${min}–${max} BPM`;
}

function getAI(_apiKeyOverride?: string | null) {
  const uid = String(auth.currentUser?.uid || '').trim();
  if (!uid) {
    throw new Error('로그인이 필요합니다.');
  }

  // The personal Gemini key never enters the browser. Prompt construction remains in the app,
  // while the authenticated Firebase Function reads the user key and calls Gemini server-side.
  if (!aiInstance || aiInstanceKey !== uid) {
    aiInstance = createGeminiServerProxy();
    aiInstanceKey = uid;
  }

  return aiInstance;
}

type GeminiAuditRequestMeta = { context: string; fallbackAttempt: number };
const geminiAuditRequestMeta = new WeakMap<object, GeminiAuditRequestMeta>();

type GeminiGenerationRequestBudget = {
  maxRequests: number;
  maxCorrectionRequests: number;
  usedRequests: number;
  usedCorrectionRequests: number;
};

const GEMINI_GENERATION_MAX_REQUESTS = 3;
const GEMINI_GENERATION_MAX_CORRECTION_REQUESTS = 1;
const AUTO_LANGUAGE_MIX_RETRY_ENABLED = false;
const geminiGenerationRequestBudgets = new Map<string, GeminiGenerationRequestBudget>();

class GeminiRequestBudgetExceededError extends Error {
  readonly code = 'SORIDRAW_GEMINI_REQUEST_BUDGET_EXCEEDED';

  constructor(message: string) {
    super(message);
    this.name = 'GeminiRequestBudgetExceededError';
  }
}

function beginGeminiGenerationRequestBudget(sessionId: string): void {
  if (!sessionId) return;
  geminiGenerationRequestBudgets.set(sessionId, {
    maxRequests: GEMINI_GENERATION_MAX_REQUESTS,
    maxCorrectionRequests: GEMINI_GENERATION_MAX_CORRECTION_REQUESTS,
    usedRequests: 0,
    usedCorrectionRequests: 0,
  });
}

function endGeminiGenerationRequestBudget(sessionId: string): void {
  if (!sessionId) return;
  geminiGenerationRequestBudgets.delete(sessionId);
}

function isInitialSongGenerationContext(context: string): boolean {
  const clean = String(context || '').trim();
  return clean === 'generateSong'
    || clean === 'generateSongCompactFallback'
    || clean.startsWith('generateSong v2');
}

function isFinalHardBanSafetyContext(context: string): boolean {
  const clean = String(context || '').trim();
  return clean === 'rewriteLyricHardBanCards'
    || clean === 'rewriteLyricHardBanLines'
    || clean === 'rewriteLyricHardBanLinesSecondPass';
}

function consumeGeminiGenerationRequestBudget(
  sessionId: string,
  context: string,
  fallbackAttempt = 1,
): void {
  const budget = geminiGenerationRequestBudgets.get(sessionId);
  if (!budget) return;

  // Final hard-ban editing is an output-safety obligation, not a discretionary quality retry.
  // It still consumes the absolute 3-request ceiling, but it must not be blocked merely because
  // the one allowed structure/density quality correction already ran.
  const isCorrection = !isInitialSongGenerationContext(context) && !isFinalHardBanSafetyContext(context);
  const isNewCorrectionOperation = isCorrection && fallbackAttempt <= 1;
  if (budget.usedRequests >= budget.maxRequests) {
    throw new GeminiRequestBudgetExceededError(
      `곡 생성 Gemini 호출 상한(${budget.maxRequests}회)에 도달해 ${context} 호출을 생략했습니다.`,
    );
  }
  // A temporary 429/5xx failure inside the single permitted correction may retry once on the
  // fallback model. That physical fallback request still consumes the absolute request ceiling,
  // but it is not a second correction operation.
  if (isNewCorrectionOperation && budget.usedCorrectionRequests >= budget.maxCorrectionRequests) {
    throw new GeminiRequestBudgetExceededError(
      `곡 생성 자동 보정 호출 상한(${budget.maxCorrectionRequests}회)에 도달해 ${context} 호출을 생략했습니다.`,
    );
  }

  budget.usedRequests += 1;
  if (isNewCorrectionOperation) budget.usedCorrectionRequests += 1;
}

function withGeminiAuditRequestMeta<T extends object>(
  params: T,
  context: string,
  fallbackAttempt = 1,
): T {
  geminiAuditRequestMeta.set(params, {
    context: String(context || 'Gemini 호출').trim() || 'Gemini 호출',
    fallbackAttempt: Math.max(1, Math.round(Number(fallbackAttempt) || 1)),
  });
  return params;
}

function getAuditedAI(
  apiKeyOverride?: string | null,
  auditSessionId?: string | null,
): GoogleGenAI {
  const ai = getAI(apiKeyOverride);
  const sessionId = String(auditSessionId || '').trim();
  if (!sessionId) return ai;

  const originalModels = (ai as any).models;
  const modelsProxy = new Proxy(originalModels, {
    get(target, property, receiver) {
      if (property !== 'generateContent') {
        const value = Reflect.get(target, property, receiver);
        return typeof value === 'function' ? value.bind(target) : value;
      }
      return async (params: any) => {
        const meta = params && typeof params === 'object'
          ? geminiAuditRequestMeta.get(params)
          : undefined;
        const context = meta?.context || 'Gemini 호출';
        consumeGeminiGenerationRequestBudget(sessionId, context, meta?.fallbackAttempt || 1);
        const startedAtMs = Date.now();
        const model = String(params?.model || 'unknown');
        try {
          const forwardedParams = params && typeof params === 'object'
            ? {
                ...params,
                __soridrawMeta: {
                  sessionId,
                  context,
                  fallbackAttempt: meta?.fallbackAttempt || 1,
                },
              }
            : params;
          const response = await target.generateContent.call(target, forwardedParams);
          recordGeminiAuditCall({
            sessionId,
            context,
            model,
            status: 'success',
            startedAtMs,
            response,
            fallbackAttempt: meta?.fallbackAttempt || 1,
          });
          return response;
        } catch (error) {
          recordGeminiAuditCall({
            sessionId,
            context,
            model,
            status: 'failed',
            startedAtMs,
            fallbackAttempt: meta?.fallbackAttempt || 1,
            error,
          });
          throw error;
        }
      };
    },
  });

  return new Proxy(ai as any, {
    get(target, property, receiver) {
      if (property === 'models') return modelsProxy;
      const value = Reflect.get(target, property, receiver);
      return typeof value === 'function' ? value.bind(target) : value;
    },
  }) as GoogleGenAI;
}

const GEMINI_TEXT_MODEL_CHAIN = [
  "gemini-3.5-flash",
  "gemini-3-flash-preview",
  "gemini-3.1-flash-lite",
  "gemini-2.5-flash",
  "gemini-2.5-flash-lite",
];
const GEMINI_TEMPORARY_PREFERRED_MODEL_MS = 2 * 60 * 1000;
let geminiTemporaryPreferredModel = '';
let geminiTemporaryPreferredUntil = 0;

const GEMINI_FALLBACK_STABILITY_INSTRUCTION = `
[FALLBACK MODEL SAFETY MODE]
- Prioritize structural stability over creative reinterpretation.
- Keep the active final production prompt structure defined by the current generation engine.
- Classic engine labels: [Genre], [Instruments], [Atmosphere], [Vocals], [Arrangement].
- Version 2 engine labels: [Genre], [Sound], [Mood], [Vocals], [Production].
- Do not invent extra vocal roles. If the user selected solo vocal, keep it solo.
- Do not convert a vocal song into instrumental. Use instrumental/no vocals only when instrumental BGM or no-lyrics mode is explicitly active.
- Preserve direct user input above automatic keyword interpretation.
- Keep lines concise, but do not remove essential vocal character details.
- Return valid JSON exactly matching the requested schema.
`.trim();

function collectGeminiErrorFragments(
  error: any,
  depth = 0,
  seen: Set<any> = new Set(),
): string[] {
  if (error == null || depth > 4) return [];
  if (typeof error === 'string' || typeof error === 'number' || typeof error === 'boolean') {
    return [String(error)];
  }
  if (typeof error !== 'object') return [String(error)];
  if (seen.has(error)) return [];
  seen.add(error);

  const fragments: string[] = [];
  const push = (value: unknown) => {
    const text = String(value ?? '').trim();
    if (text) fragments.push(text);
  };

  push(error.name);
  push(error.message);
  push(error.status);
  push(error.statusText);
  push(error.code);

  const nestedKeys = ['error', 'cause', 'response', 'data', 'details', 'body'];
  nestedKeys.forEach((key) => {
    if ((error as any)[key] != null) {
      fragments.push(...collectGeminiErrorFragments((error as any)[key], depth + 1, seen));
    }
  });

  try {
    const serialized = JSON.stringify(error, Object.getOwnPropertyNames(error));
    if (serialized && serialized !== '{}') fragments.push(serialized);
  } catch {
    // Ignore circular/non-serializable SDK internals. The explicit fields above are enough.
  }

  return fragments;
}

function describeGeminiError(error: any): string {
  return Array.from(new Set(collectGeminiErrorFragments(error)))
    .join(' | ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getGeminiErrorCode(error: any): number {
  const candidates = [
    error?.code,
    error?.error?.code,
    error?.response?.status,
    error?.response?.data?.code,
    error?.cause?.code,
  ];
  for (const value of candidates) {
    const parsed = Number(value);
    if (Number.isFinite(parsed) && parsed > 0) return parsed;
  }
  const text = describeGeminiError(error);
  const match = text.match(/(?:^|\D)(400|401|403|404|408|409|429|500|502|503|504)(?:\D|$)/);
  return match ? Number(match[1]) : 0;
}

function getGeminiErrorStatus(error: any): string {
  const candidates = [
    error?.status,
    error?.error?.status,
    error?.response?.data?.status,
    error?.cause?.status,
  ];
  for (const value of candidates) {
    const normalized = String(value || '').trim().toUpperCase();
    if (normalized) return normalized;
  }
  const text = describeGeminiError(error).toUpperCase();
  const known = ['RESOURCE_EXHAUSTED', 'UNAVAILABLE', 'DEADLINE_EXCEEDED', 'INVALID_ARGUMENT'];
  return known.find((status) => text.includes(status)) || '';
}

function isGeminiRequestSchemaError(error: any): boolean {
  const text = describeGeminiError(error).toLowerCase();
  const status = getGeminiErrorStatus(error);
  const code = getGeminiErrorCode(error);
  const hasSchemaMarker = (
    text.includes('generation_config.response_schema') ||
    text.includes('response_schema') ||
    text.includes('invalid json payload') ||
    text.includes('unknown name') ||
    text.includes('fieldviolations') ||
    text.includes('invalid value at generation_config')
  );
  return hasSchemaMarker && (code === 400 || status === 'INVALID_ARGUMENT' || !code);
}

function isGeminiRetryableError(error: any): boolean {
  const text = describeGeminiError(error).toLowerCase();
  const status = getGeminiErrorStatus(error);
  const code = getGeminiErrorCode(error);
  // 429 / quota exhaustion is project-level and usually affects fallback models too.
  // Stop immediately so one user action cannot burn another request against the same personal project.
  return (
    code === 500 ||
    code === 502 ||
    code === 503 ||
    code === 504 ||
    status === "UNAVAILABLE" ||
    status === "DEADLINE_EXCEEDED" ||
    text.includes("overloaded") ||
    text.includes("unavailable") ||
    text.includes("temporarily")
  );
}

function withFallbackSafetyInstruction(config: any, attemptIndex: number): any {
  if (attemptIndex <= 0) return config;
  const baseInstruction = config?.systemInstruction ? String(config.systemInstruction) : "";
  return {
    ...(config || {}),
    systemInstruction: [baseInstruction, GEMINI_FALLBACK_STABILITY_INSTRUCTION]
      .filter(Boolean)
      .join("\n\n"),
  };
}

function getGeminiFallbackReason(error: any): string {
  const text = describeGeminiError(error).toLowerCase();
  const status = getGeminiErrorStatus(error).toLowerCase();
  const code = getGeminiErrorCode(error);
  if (code === 429 || status.includes("resource_exhausted") || text.includes("quota")) return "quota_or_rate_limit";
  if (text.includes("rate limit") || text.includes("429")) return "quota_or_rate_limit";
  if (status.includes("unavailable") || text.includes("unavailable") || text.includes("overloaded")) return "model_unavailable_or_overloaded";
  if (code >= 500 || status.includes("deadline") || text.includes("temporarily")) return "temporary_server_error";
  return "generation_error";
}

function parseGeminiJsonObject(rawText: string): any {
  const raw = String(rawText || '').trim();
  if (!raw) throw new Error('empty JSON response');
  const candidates = [
    raw,
    raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim(),
  ];
  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    candidates.push(raw.slice(firstBrace, lastBrace + 1));
  }
  let lastError: any = null;
  for (const candidate of Array.from(new Set(candidates.filter(Boolean)))) {
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && typeof parsed === 'object') return parsed;
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError || new Error('invalid JSON response');
}

interface GeminiModelUsageInfo {
  usedModel: string;
  fallbackUsed: boolean;
  fallbackFrom?: string | null;
  fallbackReason?: string | null;
  attemptedModels: string[];
}

async function generateContentWithModelFallback(
  ai: GoogleGenAI,
  generateParams: any,
  context: string,
  modelChain: string[] = GEMINI_TEXT_MODEL_CHAIN,
): Promise<any> {
  let lastError: any = null;
  let firstFailedModel: string | null = null;
  let firstFallbackReason: string | null = null;
  const attemptedModels: string[] = [];

  const baseLimitedModelChain = modelChain.slice(0, 2);
  const hasTemporaryPreferredModel = Boolean(
    geminiTemporaryPreferredModel
    && geminiTemporaryPreferredUntil > Date.now()
    && baseLimitedModelChain.includes(geminiTemporaryPreferredModel),
  );
  const limitedModelChain = hasTemporaryPreferredModel
    ? [
      geminiTemporaryPreferredModel,
      ...baseLimitedModelChain.filter((model) => model !== geminiTemporaryPreferredModel),
    ]
    : baseLimitedModelChain;
  for (let i = 0; i < limitedModelChain.length; i += 1) {
    const model = limitedModelChain[i];
    attemptedModels.push(model);
    const paramsForAttempt = {
      ...generateParams,
      model,
      config: withFallbackSafetyInstruction(generateParams.config, i),
    };
    try {
      if (i > 0) {
        console.warn(`[SORIDRAW Gemini Fallback] ${context}: retrying with ${model}`);
      }
      const response = await ai.models.generateContent(
        withGeminiAuditRequestMeta(paramsForAttempt, context, i + 1),
      );
      (response as any).__soridrawGeminiModelInfo = {
        usedModel: model,
        fallbackUsed: i > 0,
        fallbackFrom: i > 0 ? firstFailedModel || limitedModelChain[0] || null : null,
        fallbackReason: i > 0 ? firstFallbackReason || "generation_error" : null,
        attemptedModels,
      } satisfies GeminiModelUsageInfo;
      if (i > 0 || hasTemporaryPreferredModel) {
        geminiTemporaryPreferredModel = model;
        geminiTemporaryPreferredUntil = Date.now() + GEMINI_TEMPORARY_PREFERRED_MODEL_MS;
      }
      return response;
    } catch (error) {
      lastError = error;
      if (hasTemporaryPreferredModel && model === geminiTemporaryPreferredModel) {
        geminiTemporaryPreferredModel = '';
        geminiTemporaryPreferredUntil = 0;
      }
      if (!firstFailedModel) {
        firstFailedModel = model;
        firstFallbackReason = getGeminiFallbackReason(error);
      }
      console.warn(`[SORIDRAW Gemini Fallback] ${context}: ${model} failed`, error);
      // Do not launch another paid request for a prompt/schema/content error.
      // Retry at most once, and only for a temporary unavailable/server-side failure.
      // A 429/quota error stops immediately because the personal-project quota is shared.
      if (
        isGeminiRequestSchemaError(error)
        || !isGeminiRetryableError(error)
        || i >= limitedModelChain.length - 1
      ) {
        throw error;
      }
    }
  }
  throw lastError;
}


export interface CustomSectionAutoMetadataInput {
  labelKo: string;
  description?: string;
  kind?: CustomSectionKind;
  context?: "section" | "tag";
  geminiApiKey?: string;
}

export interface CustomSectionAutoMetadata {
  labelEn: string;
  tagCue: string;
  promptFull: string;
  kind?: CustomSectionKind;
  allowVocal?: boolean;
  isInstrumental?: boolean;
}

function titleCaseWords(value: string): string {
  return String(value || '')
    .replace(/[^A-Za-z0-9\s-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
}

function fallbackCustomSectionMetadata(input: CustomSectionAutoMetadataInput): CustomSectionAutoMetadata {
  const raw = `${input.labelKo || ''} ${input.description || ''}`.toLowerCase();
  const isRap = /랩|rap/.test(raw) || input.kind === 'rap';
  const isInstrumental = /연주|간주|솔로|instrument|solo|lead/.test(raw) || input.kind === 'instrumental';
  const isTransition = /전환|정지|브레이크|break|stop|transition/.test(raw) || input.kind === 'transition';
  const pairs: Array<[RegExp, string, string]> = [
    [/속삭|whisper/, 'Whisper', 'whispery'],
    [/숨죽|muted|mute/, 'Muted', 'held-back muted'],
    [/대화|dialogue|주고받/, 'Dialogue', 'call-and-response'],
    [/강한|powerful|폭발/, 'Powerful', 'powerful'],
    [/거친|rough|husky/, 'Rough', 'rough'],
    [/젖은|wet/, 'Wet', 'wet'],
    [/낮은|저음|low|deep/, 'Low', 'deep low'],
    [/높은|high|bright/, 'Bright', 'bright'],
    [/감정|emotional/, 'Emotional', 'emotional'],
    [/신스\s*리드|synth lead/, 'Synth Lead', 'synth lead'],
    [/해금|haegeum/, 'Haegeum', 'haegeum'],
    [/가야금|gayageum/, 'Gayageum', 'gayageum'],
    [/장구|janggu/, 'Janggu', 'janggu'],
    [/정적|silent|silence/, 'Silent', 'silent'],
  ];
  const words: string[] = [];
  const cues: string[] = [];
  pairs.forEach(([re, label, cue]) => {
    if (re.test(raw) && !words.includes(label)) {
      words.push(label);
      cues.push(cue);
    }
  });
  if (isRap && !words.includes('Rap')) words.push('Rap');
  if (isInstrumental && !words.some(w => /Solo|Instrumental/.test(w))) words.push(/솔로|solo|lead/.test(raw) ? 'Solo' : 'Instrumental');
  if (isTransition && !words.some(w => /Break|Stop|Transition/.test(w))) words.push('Transition');
  if (!words.length) words.push(...titleCaseWords(input.labelKo || 'Custom Section').split(' ').slice(0, 3));
  const labelEn = titleCaseWords(words.join(' ')).slice(0, 40) || 'Custom Section';
  const tagCue = (cues.join(' ') + (isRap ? ' rap delivery' : isInstrumental ? ' instrumental cue' : isTransition ? ' transition cue' : ' section cue'))
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 80);
  const promptFull = [tagCue, isRap ? 'rhythmic flow' : '', isInstrumental ? 'no vocals, no humming' : '', isTransition ? 'short reset between sections' : '']
    .filter(Boolean)
    .join(', ')
    .slice(0, 160);
  return {
    labelEn,
    tagCue,
    promptFull,
    kind: input.kind || (isInstrumental ? 'instrumental' : isRap ? 'rap' : isTransition ? 'transition' : 'other'),
    allowVocal: !(isInstrumental || isTransition),
    isInstrumental,
  };
}

export async function generateCustomSectionMetadata(input: CustomSectionAutoMetadataInput): Promise<CustomSectionAutoMetadata> {
  const fallback = fallbackCustomSectionMetadata(input);
  const labelKo = String(input.labelKo || '').trim();
  if (!labelKo) return fallback;
  const auditSessionId = startGeminiAuditSession('사용자 섹션 메타데이터 생성');
  try {
    const ai = getAuditedAI(input.geminiApiKey, auditSessionId);
    const prompt = `You are converting a Korean user-created Suno song section/tag into compact English metadata for a music app.\nReturn ONLY JSON.\nRules:\n- labelEn: short English section/tag name, Title Case, max 4 words.\n- tagCue: short lyric-tag cue, max 8 words, no brackets.\n- promptFull: fuller internal prompt, max 18 words, comma-separated, no brackets.\n- kind: one of vocal, rap, instrumental, transition, build, theme, other.\n- allowVocal false for instrumental/transition.\n- isInstrumental true only when it must contain no voice/humming/chant.\nUser Korean label: ${labelKo}\nDescription: ${input.description || ''}\nPreferred kind: ${input.kind || ''}\nContext: ${input.context || 'section'}`;
    const response = await ai.models.generateContent(withGeminiAuditRequestMeta({
      model: 'gemini-2.5-flash-lite',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            labelEn: { type: Type.STRING },
            tagCue: { type: Type.STRING },
            promptFull: { type: Type.STRING },
            kind: { type: Type.STRING },
            allowVocal: { type: Type.BOOLEAN },
            isInstrumental: { type: Type.BOOLEAN },
          },
          required: ['labelEn', 'tagCue', 'promptFull'],
        },
      },
    }, 'generateCustomSectionMetadata'));
    const text = response.text || '';
    const parsed = JSON.parse(text);
    const labelEn = titleCaseWords(parsed.labelEn || fallback.labelEn).slice(0, 40) || fallback.labelEn;
    const tagCue = String(parsed.tagCue || fallback.tagCue).replace(/[\[\]\n\r]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80) || fallback.tagCue;
    const promptFull = String(parsed.promptFull || fallback.promptFull).replace(/[\[\]\n\r]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 160) || fallback.promptFull;
    const kind = ['vocal', 'rap', 'instrumental', 'transition', 'build', 'theme', 'other'].includes(parsed.kind) ? parsed.kind as CustomSectionKind : fallback.kind;
    const result = {
      labelEn,
      tagCue,
      promptFull,
      kind,
      allowVocal: typeof parsed.allowVocal === 'boolean' ? parsed.allowVocal : fallback.allowVocal,
      isInstrumental: typeof parsed.isInstrumental === 'boolean' ? parsed.isInstrumental : fallback.isInstrumental,
    };
    finishGeminiAuditSession(auditSessionId, 'success', { resultLabel: labelEn });
    return result;
  } catch (error) {
    finishGeminiAuditSession(auditSessionId, 'failed', { error });
    console.warn('Custom section metadata generation failed, using fallback:', error);
    return fallback;
  }
}

type LegacyGenreInput = string[];
type LegacyMoodInput = string[];
type LegacyThemeInput = string[];
type LanguageCode = "ko" | "en" | "ja" | "zh" | "es" | "fr" | "de" | "ru" | "th";

type GenerationEngineVersion = "classic" | "v2";
type V1LyricWritingStyle = "default" | "kimEana";
type RapMode = "auto" | "off" | "on";

interface GenerateSongParams {
  genre: string | null;
  subGenre?: string[];
  isKpopSelected?: boolean;
  isKoreanEnglishMix?: boolean;
  englishMixRatio?: number;
  languageMixTargetLanguages?: LanguageCode[];
  moods: string[];
  themes?: string[];
  situation?: SituationConfig;
  styles?: string[];
  instrumentSounds?: string[];
  pointSounds?: string[];
  userInput: string;
  lyricDraft?: string;
  isLyricMode?: boolean;
  lyricMode?: "assist" | "preserve";
  songPrompt?: string;
  lyricsLength?: LyricsLength;
  songStructure?: SongStructure;
  useAutoDuration?: boolean;
  vocal?: VocalConfig;
  tempo?: string;
  isRandomTempo?: boolean;
  tempoSource?: "random" | "manual";
  specialPrompt?: string;
  kpopMode?: 0 | 1 | 2;
  customStructure?: CustomSectionItem[];
  sectionCueOptions?: Partial<SectionCueOptions>;
  isNoLyrics?: boolean;
  includeLyrics?: boolean;
  instrumentalBgmMode?: boolean;
  lyricLanguages?: LanguageCode[];
  customGenreInput?: string;
  customThemeInput?: string;
  customMoodInput?: string;
  customStyleInput?: string;
  customSoundInput?: string;
  geminiApiKey?: string;
  generationIndex?: number;
  generationCount?: number;
  recentStoryMemory?: string[];
  recentGeneratedTitles?: string[];
  recentGeneratedLyricSnippets?: string[];
  recentMoodThemeMemory?: string[];
  lyricClicheGuard?: any;
  generationEngineVersion?: GenerationEngineVersion;
  lyricWritingStyle?: V1LyricWritingStyle;
  __geminiAuditSessionId?: string;
  __v1SectionBlueprintContract?: V1SectionBlueprint;
}

function resolveSectionCueOptions(params?: Pick<GenerateSongParams, 'sectionCueOptions'> | null): SectionCueOptions {
  return {
    vocal: params?.sectionCueOptions?.vocal !== false,
    instrument: params?.sectionCueOptions?.instrument !== false,
  };
}

function isV1KimEanaLyricStyle(params?: Pick<GenerateSongParams, 'generationEngineVersion' | 'lyricWritingStyle'> | null): boolean {
  return !isGenerationEngineV2(params) && params?.lyricWritingStyle === 'kimEana';
}

function buildV1LyricWritingStyleInstruction(params: Pick<GenerateSongParams, 'generationEngineVersion' | 'lyricWritingStyle'>): string {
  if (isGenerationEngineV2(params)) return '';
  if (!isV1KimEanaLyricStyle(params)) {
    return `V1 LYRIC WRITING STYLE — DEFAULT (MANDATORY):
- Write freely from the resolved Story Context, genre, vocal setup, and selected section structure.
- Do not imitate a named lyricist or reuse a preset author voice.
- Do not force dialogue, everyday props, hidden-confession arcs, persona flaws, contradiction hooks, cause-and-result explanations, or a fixed emotional payoff.
- Choose diction, sentence endings, perspective, imagery level, lyric density, and section development specifically for this song.`;
  }
  return `V1 LYRIC WRITING STYLE — KIM EANA METHOD (OPTIONAL, ACTIVE):
- Use only broad craft principles: a believable persona, character-specific speech, emotional precision, singable pronunciation, and concrete behavior when it naturally belongs to the Story Context.
- A human flaw or lived detail may be used only when the current story supports it; never force one.
- Do not use stored example sentences, preset objects, preset conflicts, denial-to-confession formulas, cause-and-result explanations, or fixed chorus/endings.
- The result must still sound unique to this song rather than like a repeated imitation of one writer.`;
}

function isGenerationEngineV2(params?: Pick<GenerateSongParams, 'generationEngineVersion'> | null): boolean {
  return isPromptEngineV2(params?.generationEngineVersion);
}

function normalizeProductionPromptLabelToClassicKey(label: string): keyof FinalPromptLineMap | null {
  const normalized = String(label || '').trim().toLowerCase();
  if (normalized === 'genre') return 'genre';
  if (normalized === 'instruments' || normalized === 'sound') return 'instruments';
  if (normalized === 'atmosphere' || normalized === 'mood') return 'atmosphere';
  if (normalized === 'vocals') return 'vocals';
  if (normalized === 'arrangement' || normalized === 'production') return 'arrangement';
  return null;
}

function buildGenerationEngineOutputInstruction(params: Pick<GenerateSongParams, 'generationEngineVersion' | 'isNoLyrics'>): string {
  if (isGenerationEngineV2(params)) {
    return buildPromptEngineV2OutputInstruction({ isNoLyrics: params.isNoLyrics });
  }
  return buildPromptEngineV1OutputInstruction();
}

function renderProductionPromptForGenerationEngine(prompt: string, params: Pick<GenerateSongParams, 'generationEngineVersion'>): string {
  if (!isGenerationEngineV2(params)) return prompt;
  const map = parseFinalPromptLineMap(prompt);
  const hasAudioQuality = /\[Audio quality improved to masterpiece\]/i.test(String(prompt || ''));
  const lines = [
    `[Genre] ${cleanupPromptTail(map.genre || 'Genre-led pop fusion')}`,
    `[Sound] ${cleanupPromptTail(map.instruments || 'balanced band and synth texture')}`,
    `[Mood] ${cleanupPromptTail(map.atmosphere || 'balanced emotional air')}`,
    `[Vocals] ${cleanupPromptTail(map.vocals || 'natural solo vocal with story-aware delivery')}`,
    `[Production] ${cleanupPromptTail(map.arrangement || 'clear sectional contrast')}`,
  ];
  if (hasAudioQuality) lines.push('[Audio quality improved to masterpiece]');
  return removeAudioQualityLineWhenPromptIsNearLimit(lines.join('\n'));
}

function getRapModeFromVocal(vocal?: VocalConfig | null): RapMode {
  const raw = String((vocal as any)?.rapMode || '').toLowerCase();
  if (raw === 'off' || raw === 'on' || raw === 'auto') return raw;
  return vocal?.rap ? 'on' : 'auto';
}

function getRapModeFromParams(params: Pick<GenerateSongParams, 'vocal'>): RapMode {
  return getRapModeFromVocal(params.vocal);
}

function buildRapModeInstruction(params: Pick<GenerateSongParams, 'vocal' | 'songStructure' | 'customStructure'>): string {
  const mode = getRapModeFromParams(params);
  if (mode === 'off') {
    return 'RAP MODE: OFF. Add only "no rap" to final [Arrangement]. Do not add or relocate a Rap Section automatically. An explicitly user-built custom Rap Section remains part of the custom structure.';
  }
  if (mode === 'on') {
    const customHasRap = params.songStructure === 'custom' && (params.customStructure || []).some((item: any) => /rap/i.test(String(item?.section || item?.label || item?.labelEn || item?.tagCue || '')));
    if (params.songStructure === 'custom') {
      return customHasRap
        ? 'RAP MODE: ON. Preserve the user-positioned custom Rap Section with real lyric lines; never move it. Add "rap section" to final [Arrangement].'
        : "RAP MODE: ON, but Custom structure is exact. Do not invent or relocate a Rap Section outside the user's custom order. Use rap delivery only inside an existing user-approved sung section when its cue permits it; add 'rap delivery' to final [Arrangement].";
    }
    return "RAP MODE: ON. Follow the V1 Section Blueprint exactly. Non-rap songs use one real Rap Section in a musically suitable second-act position; rap-dominant songs may use the blueprint's repeated Rap Sections. Do not move Rap Section to a different position. Add 'rap section' to final [Arrangement].";
  }
  return 'RAP MODE: AUTO. Include Rap Section only when the V1 Section Blueprint contains it because the genre, selected rapper role, custom structure, or direct instruction supports rap. Do not invent or relocate Rap Section outside the blueprint.';
}

type GenerateSongInput =
  | [
      LegacyGenreInput,
      LegacyMoodInput,
      LegacyThemeInput,
      string,
      string?,
      LyricsLength?,
      SongStructure?,
      boolean?,
      number?,
      number?,
      boolean?,
      string?,
      string?,
      (0 | 1 | 2)?,
    ]
  | [GenerateSongParams];

const NON_EMPTY = (value: string | null | undefined): value is string =>
  typeof value === "string" && value.trim().length > 0;

function sentenceCase(value: string): string {
  return value
    .replace(/[-_]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

function formatTempoForPrompt(tempo?: string | null): string {
  const raw = String(tempo || "").trim();
  if (!raw) return "";

  const formatted = raw
    .replace(/^Between\s+/i, "")
    .replace(/^Exactly\s+/i, "")
    .replace(/\s+and\s+/i, "–")
    .replace(/\s*BPM\s*/gi, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!formatted) return "";
  return /BPM$/i.test(formatted) ? formatted : `${formatted} BPM`;
}

function buildTempoPromptPhrase(
  params: Pick<GenerateSongParams, "tempo" | "isRandomTempo" | "tempoSource">,
): string {
  const tempo = formatTempoForPrompt(params.tempo);
  if (!tempo) return "";

  if (params.tempoSource === "random" || params.isRandomTempo) {
    return `tempo optimized around ${tempo}`;
  }

  return `tempo set to ${tempo}`;
}

function isSeparatorLikeId(value: unknown): boolean {
  return /^separator[-_]/i.test(String(value || '').trim());
}

function isSeparatorLikeItem(item: any): boolean {
  return Boolean(item?.kind === 'separator' || isSeparatorLikeId(item?.id));
}

function filterPromptSelectionIds(values: string[] = []): string[] {
  return values.filter((value) => value && !isSeparatorLikeId(value));
}

function normalizeCatalogCompareText(value: unknown): string {
  return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function matchesCatalogValue(item: any, value: string): boolean {
  const normalized = normalizeCatalogCompareText(decodeSoridrawCustomKeyword(value));
  if (!normalized) return false;
  return [item?.id, item?.label, item?.labelKo]
    .map(normalizeCatalogCompareText)
    .filter(Boolean)
    .some((candidate) => candidate === normalized);
}

function resolveStyleItem(value: string) {
  if (isSeparatorLikeId(value)) return undefined;
  const decoded = decodeSoridrawCustomKeyword(value);
  const rawValue = String(decoded || '').trim();
  const canonicalValue = STYLE_VARIANT_ALIAS_TO_ID[rawValue] || STYLE_VARIANT_ALIAS_TO_ID[rawValue.toLowerCase()] || value;
  const found = SOUND_STYLES.find((item) => matchesCatalogValue(item, canonicalValue));
  return isSeparatorLikeItem(found) ? undefined : found;
}

function resolveInstrumentSoundItem(value: string) {
  if (isSeparatorLikeId(value)) return undefined;
  const found = INSTRUMENT_SOUNDS.find((item) => matchesCatalogValue(item, value));
  return isSeparatorLikeItem(found) ? undefined : found;
}

function resolveThemeItem(value: string) {
  if (isSeparatorLikeId(value)) return undefined;
  return THEMES.find((item) => matchesCatalogValue(item, value));
}



